package optimizer

import (
	"strings"
	"testing"
)

// TestPyDate checks the date port against CPython 3.14 and dateutil 2.9: each row adds
// interval(unit, n) to a date or datetime, or floors it to unit under a WEEK_OFFSET, and records
// str() of the result, generated by running the same code as simplify.py.
func TestPyDate(t *testing.T) {
	for _, tc := range []struct {
		op, in, unit  string
		n, weekOffset int
		want          string
	}{
		{"add", "2021-01-31", "month", 1, 0, "2021-02-28"},
		{"add", "2021-01-31", "month", -1, 0, "2020-12-31"},
		{"add", "2021-01-31", "year", 1, 0, "2022-01-31"},
		{"add", "2021-01-31", "quarter", 1, 0, "2021-04-30"},
		{"add", "2021-01-31", "week", 2, 0, "2021-02-14"},
		{"add", "2021-01-31", "day", -3, 0, "2021-01-28"},
		{"add", "2021-01-31", "hour", 5, 0, "2021-01-31 05:00:00"},
		{"add", "2021-01-31", "millisecond", 1500, 0, "2021-01-31 00:00:01.500000"},
		{"floor", "2021-01-31", "year", 0, 0, "2021-01-01"},
		{"floor", "2021-01-31", "year", 0, -1, "2021-01-01"},
		{"floor", "2021-01-31", "quarter", 0, 0, "2021-01-01"},
		{"floor", "2021-01-31", "quarter", 0, -1, "2021-01-01"},
		{"floor", "2021-01-31", "month", 0, 0, "2021-01-01"},
		{"floor", "2021-01-31", "month", 0, -1, "2021-01-01"},
		{"floor", "2021-01-31", "week", 0, 0, "2021-01-25"},
		{"floor", "2021-01-31", "week", 0, -1, "2021-01-31"},
		{"floor", "2021-01-31", "day", 0, 0, "2021-01-31"},
		{"floor", "2021-01-31", "day", 0, -1, "2021-01-31"},
		{"add", "2020-02-29", "month", 1, 0, "2020-03-29"},
		{"add", "2020-02-29", "month", -1, 0, "2020-01-29"},
		{"add", "2020-02-29", "year", 1, 0, "2021-02-28"},
		{"add", "2020-02-29", "quarter", 1, 0, "2020-05-29"},
		{"add", "2020-02-29", "week", 2, 0, "2020-03-14"},
		{"add", "2020-02-29", "day", -3, 0, "2020-02-26"},
		{"add", "2020-02-29", "hour", 5, 0, "2020-02-29 05:00:00"},
		{"add", "2020-02-29", "millisecond", 1500, 0, "2020-02-29 00:00:01.500000"},
		{"floor", "2020-02-29", "year", 0, 0, "2020-01-01"},
		{"floor", "2020-02-29", "year", 0, -1, "2020-01-01"},
		{"floor", "2020-02-29", "quarter", 0, 0, "2020-01-01"},
		{"floor", "2020-02-29", "quarter", 0, -1, "2020-01-01"},
		{"floor", "2020-02-29", "month", 0, 0, "2020-02-01"},
		{"floor", "2020-02-29", "month", 0, -1, "2020-02-01"},
		{"floor", "2020-02-29", "week", 0, 0, "2020-02-24"},
		{"floor", "2020-02-29", "week", 0, -1, "2020-02-23"},
		{"floor", "2020-02-29", "day", 0, 0, "2020-02-29"},
		{"floor", "2020-02-29", "day", 0, -1, "2020-02-29"},
		{"add", "2021-03-15 10:30:45.123456", "month", 1, 0, "2021-04-15 10:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "month", -1, 0, "2021-02-15 10:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "year", 1, 0, "2022-03-15 10:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "quarter", 1, 0, "2021-06-15 10:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "week", 2, 0, "2021-03-29 10:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "day", -3, 0, "2021-03-12 10:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "hour", 5, 0, "2021-03-15 15:30:45.123456"},
		{"add", "2021-03-15 10:30:45.123456", "millisecond", 1500, 0, "2021-03-15 10:30:46.623456"},
		{"floor", "2021-03-15 10:30:45.123456", "year", 0, 0, "2021-01-01 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "year", 0, -1, "2021-01-01 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "quarter", 0, 0, "2021-01-01 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "quarter", 0, -1, "2021-01-01 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "month", 0, 0, "2021-03-01 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "month", 0, -1, "2021-03-01 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "week", 0, 0, "2021-03-15 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "week", 0, -1, "2021-03-14 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "day", 0, 0, "2021-03-15 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "day", 0, -1, "2021-03-15 00:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "hour", 0, 0, "2021-03-15 10:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "hour", 0, -1, "2021-03-15 10:00:00"},
		{"floor", "2021-03-15 10:30:45.123456", "minute", 0, 0, "2021-03-15 10:30:00"},
		{"floor", "2021-03-15 10:30:45.123456", "minute", 0, -1, "2021-03-15 10:30:00"},
		{"floor", "2021-03-15 10:30:45.123456", "second", 0, 0, "2021-03-15 10:30:45"},
		{"floor", "2021-03-15 10:30:45.123456", "second", 0, -1, "2021-03-15 10:30:45"},
		{"floor", "2021-03-15 10:30:45.123456", "millisecond", 0, 0, "2021-03-15 10:30:45.123000"},
		{"floor", "2021-03-15 10:30:45.123456", "millisecond", 0, -1, "2021-03-15 10:30:45.123000"},
		{"add", "2021-12-31 23:59:59", "month", 1, 0, "2022-01-31 23:59:59"},
		{"add", "2021-12-31 23:59:59", "month", -1, 0, "2021-11-30 23:59:59"},
		{"add", "2021-12-31 23:59:59", "year", 1, 0, "2022-12-31 23:59:59"},
		{"add", "2021-12-31 23:59:59", "quarter", 1, 0, "2022-03-31 23:59:59"},
		{"add", "2021-12-31 23:59:59", "week", 2, 0, "2022-01-14 23:59:59"},
		{"add", "2021-12-31 23:59:59", "day", -3, 0, "2021-12-28 23:59:59"},
		{"add", "2021-12-31 23:59:59", "hour", 5, 0, "2022-01-01 04:59:59"},
		{"add", "2021-12-31 23:59:59", "millisecond", 1500, 0, "2022-01-01 00:00:00.500000"},
		{"floor", "2021-12-31 23:59:59", "year", 0, 0, "2021-01-01 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "year", 0, -1, "2021-01-01 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "quarter", 0, 0, "2021-10-01 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "quarter", 0, -1, "2021-10-01 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "month", 0, 0, "2021-12-01 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "month", 0, -1, "2021-12-01 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "week", 0, 0, "2021-12-27 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "week", 0, -1, "2021-12-26 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "day", 0, 0, "2021-12-31 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "day", 0, -1, "2021-12-31 00:00:00"},
		{"floor", "2021-12-31 23:59:59", "hour", 0, 0, "2021-12-31 23:00:00"},
		{"floor", "2021-12-31 23:59:59", "hour", 0, -1, "2021-12-31 23:00:00"},
		{"floor", "2021-12-31 23:59:59", "minute", 0, 0, "2021-12-31 23:59:00"},
		{"floor", "2021-12-31 23:59:59", "minute", 0, -1, "2021-12-31 23:59:00"},
		{"floor", "2021-12-31 23:59:59", "second", 0, 0, "2021-12-31 23:59:59"},
		{"floor", "2021-12-31 23:59:59", "second", 0, -1, "2021-12-31 23:59:59"},
		{"floor", "2021-12-31 23:59:59", "millisecond", 0, 0, "2021-12-31 23:59:59"},
		{"floor", "2021-12-31 23:59:59", "millisecond", 0, -1, "2021-12-31 23:59:59"},
		{"add", "2021-07-04", "month", 1, 0, "2021-08-04"},
		{"add", "2021-07-04", "month", -1, 0, "2021-06-04"},
		{"add", "2021-07-04", "year", 1, 0, "2022-07-04"},
		{"add", "2021-07-04", "quarter", 1, 0, "2021-10-04"},
		{"add", "2021-07-04", "week", 2, 0, "2021-07-18"},
		{"add", "2021-07-04", "day", -3, 0, "2021-07-01"},
		{"add", "2021-07-04", "hour", 5, 0, "2021-07-04 05:00:00"},
		{"add", "2021-07-04", "millisecond", 1500, 0, "2021-07-04 00:00:01.500000"},
		{"floor", "2021-07-04", "year", 0, 0, "2021-01-01"},
		{"floor", "2021-07-04", "year", 0, -1, "2021-01-01"},
		{"floor", "2021-07-04", "quarter", 0, 0, "2021-07-01"},
		{"floor", "2021-07-04", "quarter", 0, -1, "2021-07-01"},
		{"floor", "2021-07-04", "month", 0, 0, "2021-07-01"},
		{"floor", "2021-07-04", "month", 0, -1, "2021-07-01"},
		{"floor", "2021-07-04", "week", 0, 0, "2021-06-28"},
		{"floor", "2021-07-04", "week", 0, -1, "2021-07-04"},
		{"floor", "2021-07-04", "day", 0, 0, "2021-07-04"},
		{"floor", "2021-07-04", "day", 0, -1, "2021-07-04"},
	} {
		var d pyDate
		var ok bool
		if strings.Contains(tc.in, " ") {
			d, ok = pyFromISODatetime(tc.in)
		} else {
			d, ok = pyFromISODate(tc.in)
		}
		if !ok {
			t.Fatalf("parse %q failed", tc.in)
		}
		var got pyDate
		if tc.op == "add" {
			got = interval(tc.unit, tc.n).addTo(d)
		} else {
			got = datetimeFloor(d, tc.unit, tc.weekOffset)
		}
		if got.String() != tc.want {
			t.Errorf("%s(%s, %s, %d, %d) = %s, want %s", tc.op, tc.in, tc.unit, tc.n, tc.weekOffset, got, tc.want)
		}
	}
}
